const glow = (el, g) => { const v = Math.max(0, Math.min(1, g)).toFixed(2); if (el.__g !== v) { el.__g = v; el.style.setProperty("--g", v); } };
const glowAll = (root, g) => root.querySelectorAll(".neurogenesis-amyloid-4-g").forEach((e) => glow(e, g));
const mv = (el, d) => { const t = translateAlong(C.P, d); if (el.__t !== t) { el.__t = t; el.setAttribute("transform", t); } };
const _cache = new WeakMap();
const redraw = (el, key, fn) => { if (_cache.get(el) === key) return; _cache.set(el, key); el.innerHTML = fn(); };


